-- 027 — comunidades. O HackaHub deixa de ser a casa de uma organização só:
-- cada comunidade (faculdade, coletivo, cidade, empresa) tem página, membros,
-- mural, avisos e os hackathons dela. A Hack Inova vira uma comunidade como
-- qualquer outra, com as edições que ela já fez.

CREATE TABLE communities (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  -- endereço público: /comunidade/<slug>
  "slug" TEXT NOT NULL UNIQUE CHECK ("slug" ~ '^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$'),
  "name" TEXT NOT NULL,
  "description" TEXT,
  -- "Sorocaba, SP"; online = 1 quando a comunidade não é de uma cidade
  "city" TEXT,
  "online" INTEGER NOT NULL DEFAULT 0,
  "website" TEXT,
  "instagram" TEXT,
  "linkedin" TEXT,
  "discord" TEXT,
  "groupUrl" TEXT,
  "logoUrl" TEXT,
  "coverUrl" TEXT,
  -- quem criou (vira dono). Nulo na Hack Inova, que o admin global administra.
  -- Conta excluída: a linha de members fica anonimizada e a comunidade fica,
  -- sem dono (o vínculo em community_members some na exclusão)
  "createdBy" INTEGER REFERENCES members("id"),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "updatedAt" TEXT,
  -- moderação do admin global: escondida some das listas e da página pública
  "hidden" INTEGER NOT NULL DEFAULT 0,
  -- selo dado pelo admin global
  "verified" INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_communities_created ON communities ("createdAt" DESC);

CREATE TABLE community_members (
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "role" TEXT NOT NULL DEFAULT 'membro' CHECK ("role" IN ('dono', 'organizador', 'membro')),
  "joinedAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("communityId", "memberId")
);
CREATE INDEX idx_community_members_member ON community_members ("memberId");

-- convite de organizador por e-mail (mesmo padrão do edition_role_invites):
-- vale na hora pra quem já tem conta; senão é resgatado no primeiro login
CREATE TABLE community_invites (
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "email" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'organizador' CHECK ("role" IN ('organizador')),
  "invitedBy" INTEGER REFERENCES members("id"),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("communityId", "email")
);
CREATE INDEX idx_community_invites_email ON community_invites ("email");

-- avisos da comunidade (dono/organizador escreve, os membros recebem)
CREATE TABLE community_notices (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "createdBy" INTEGER REFERENCES members("id"),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now()
);
CREATE INDEX idx_community_notices_community ON community_notices ("communityId", "id" DESC);

-- "denunciar" na página da comunidade: cai na fila do admin global
CREATE TABLE community_reports (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "memberId" INTEGER REFERENCES members("id"),
  "reason" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "resolvedAt" TEXT
);

-- hackathon de uma comunidade (nulo = evento externo do radar ou edição
-- antiga do painel sem comunidade)
ALTER TABLE hackathons ADD COLUMN "communityId" INTEGER REFERENCES communities("id");
CREATE INDEX idx_hackathons_community ON hackathons ("communityId");
-- quando a edição foi criada (moderação: "hackathons novos" no /admin). As
-- antigas ficam sem data; só as novas ganham o default.
ALTER TABLE hackathons ADD COLUMN "createdAt" TEXT;
ALTER TABLE hackathons ALTER COLUMN "createdAt" SET DEFAULT sqlite_now();
-- quem organiza sozinho escreve a descrição e o link do evento (site,
-- Instagram) direto no HackaHub
ALTER TABLE hackathons ADD COLUMN "description" TEXT;
ALTER TABLE hackathons ADD COLUMN "infoUrl" TEXT;

-- mural da comunidade: o mesmo feed, com escopo
ALTER TABLE posts ADD COLUMN "communityId" INTEGER REFERENCES communities("id");
CREATE INDEX idx_posts_community ON posts ("communityId");

-- a Hack Inova vira uma comunidade, com selo e sem dono (o admin administra)
INSERT INTO communities ("slug", "name", "description", "city", "verified")
VALUES ('hack-inova', 'Hack Inova', 'Hackathons universitários em São Paulo e região.', 'São Paulo, SP', 1)
ON CONFLICT ("slug") DO NOTHING;

-- as edições que ela já fez (seed) e as que ela abriu pelo painel passam a
-- ser dela. O seed faz o mesmo em banco novo (lib/seed.ts).
UPDATE hackathons SET "communityId" = (SELECT "id" FROM communities WHERE "slug" = 'hack-inova')
WHERE "communityId" IS NULL
  AND ("source" = 'seed' OR ("source" = 'painel' AND lower("organizer") LIKE '%hack inova%'));
